mapper.select:
SELECT 
FROM knowledge_parse_job

    AND list_hidden = '0'

        AND knowledge_id = #{bo.knowledgeId}


        AND document_id = #{bo.documentId}


        AND document_version_id = #{bo.documentVersionId}


        AND job_type = #{bo.jobType}


        AND status = #{bo.status}


        AND target_index_version = #{bo.targetIndexVersion}


ORDER BY create_time DESC, id DESC

mapper.update:
UPDATE knowledge_parse_job SET status = #{cancelledStatus}
WHERE id = #{id} AND status IN
#{status}

UPDATE knowledge_parse_job
SET status = #{pendingStatus}, progress = 0, error_code = NULL, error_message = NULL,
    attempt_count = #{attemptCount}
WHERE id = #{id} AND list_hidden = #{visible} AND status IN
#{status}

UPDATE knowledge_parse_job SET list_hidden = #{hidden}, update_time = NOW()
WHERE id = #{id} AND list_hidden = #{visible} AND status IN

    #{status}
